css:
:root{
  --font-sans:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  --font-mono:ui-monospace,SFMono-Regular,"SF Mono",Menlo,Monaco,Consolas,"Liberation Mono","Courier New",monospace;
  --bg:#F4F3EE;
  --surface:#FCFBF8;
  --surface-soft:#F8F6F0;
  --surface-field:#FFFEFB;
  --ink:#1B1E1A;
  --muted:#5C6158;
  --faint:#858A7F;
  --line:#E3E0D7;
  --line-strong:#D2CFC4;
  --control:#908D81;
  --accent:#1F5B45;
  --accent-soft:#E7EFE9;
  --row-hover:#F7F5EE;
  --paid-bg:#E4F0E7;
  --paid-line:#CBE2D2;
  --paid-ink:#1C563A;
  --paid-dot:#2B7A4F;
  --pending-bg:#FBF0D9;
  --pending-line:#F0DFB8;
  --pending-ink:#77480A;
  --pending-dot:#B47B12;
  --refunded-bg:#F7E8E3;
  --refunded-line:#EAD2C9;
  --refunded-ink:#87331F;
  --refunded-dot:#AC4A34;
  --radius-panel:12px;
  --radius-control:8px;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{
  margin:0;
  background-color:var(--bg);
  background-image:radial-gradient(1100px 520px at 50% -18%,#FBFAF6 0%,#F4F3EE 62%);
  background-repeat:no-repeat;
  color:var(--ink);
  font-family:var(--font-sans);
  font-size:14px;
  line-height:1.5;
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
}
a{color:inherit}
button,input,select{font:inherit}
button{cursor:pointer}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap;border:0}
.skip-link{position:fixed;left:16px;top:-64px;z-index:100;background:var(--ink);color:#FFFDF8;text-decoration:none;padding:10px 14px;border-radius:8px;font-size:13px;font-weight:600;transition:top .15s ease}
.skip-link:focus{top:12px}
a:focus-visible,button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}

.appbar{position:sticky;top:0;z-index:20;background:var(--surface);border-bottom:1px solid var(--line)}
.appbar-inner{max-width:1180px;margin:0 auto;padding:0 32px;height:58px;display:flex;align-items:center;gap:28px}
.brand{display:flex;align-items:center;gap:9px;min-height:32px;flex:0 0 auto;text-decoration:none}
.brand-mark{display:block;flex:0 0 auto}
.brand-name{font-size:15px;font-weight:600;letter-spacing:-.01em;color:var(--ink)}
.mainnav{display:flex;align-items:stretch;gap:24px;height:58px}
.mainnav a{display:flex;align-items:center;position:relative;color:var(--muted);text-decoration:none;font-size:13px;font-weight:500}
.mainnav a:hover{color:var(--ink)}
.mainnav a[aria-current="page"]{color:var(--ink);font-weight:600}
.mainnav a[aria-current="page"]::after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:2px;background:var(--accent);border-radius:2px 2px 0 0}
.appbar-right{margin-left:auto;display:flex;align-items:center;gap:12px}
.account{display:flex;align-items:center;gap:8px;height:38px;padding:0 8px 0 5px;border:1px solid transparent;border-radius:9px;background:transparent;color:var(--ink)}
.account:hover{background:#F2F0E9;border-color:var(--line)}
.avatar{width:27px;height:27px;border-radius:50%;background:#E6EDE5;border:1px solid #D5DFD3;color:#2B4C3A;display:grid;place-items:center;font-size:10px;font-weight:700;letter-spacing:.02em}
.account-name{font-size:12.5px;font-weight:500;color:var(--muted)}
.account .chev{color:var(--faint)}

.page{max-width:1180px;margin:0 auto;padding:40px 32px 64px}
.page-head{margin-bottom:22px}
.eyebrow{margin:0 0 10px;font-family:var(--font-mono);font-size:11px;line-height:1;letter-spacing:.13em;text-transform:uppercase;color:var(--muted);font-weight:500}
.page-head h1{margin:0;font-size:31px;line-height:1.1;font-weight:600;letter-spacing:-.028em;color:var(--ink)}
.lede{margin:10px 0 0;max-width:52ch;font-size:13.5px;line-height:1.55;color:var(--muted)}

.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius-panel);box-shadow:0 1px 1px rgba(27,30,26,.03),0 22px 44px -34px rgba(27,30,26,.28);overflow:hidden;scroll-margin-top:78px}
.toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:14px 18px;background:var(--surface-soft);border-bottom:1px solid var(--line)}
.search{position:relative;flex:0 1 336px;min-width:0}
.search .search-icon{position:absolute;left:11px;top:50%;transform:translateY(-50%);color:#6E7368;pointer-events:none}
.search input{width:100%;height:37px;padding:0 12px 0 34px;border:1px solid var(--control);border-radius:var(--radius-control);background:var(--surface-field);color:var(--ink);font-size:13px;appearance:none;-webkit-appearance:none;outline:none;transition:border-color .14s ease,box-shadow .14s ease}
.search input::placeholder{color:#6A6F64;opacity:1}
.search input:hover{border-color:#757267}
.search input:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(31,91,69,.16)}
.search input::-webkit-search-decoration,.search input::-webkit-search-cancel-button{-webkit-appearance:none;appearance:none}
.filter{position:relative;flex:0 0 auto}
.filter select{height:37px;min-width:166px;padding:0 32px 0 12px;border:1px solid var(--control);border-radius:var(--radius-control);background:var(--surface-field);color:var(--ink);font-size:13px;font-weight:500;appearance:none;-webkit-appearance:none;cursor:pointer;outline:none;transition:border-color .14s ease,box-shadow .14s ease}
.filter select:hover{border-color:#757267}
.filter select:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(31,91,69,.16)}
.filter .chev{position:absolute;right:10px;top:50%;transform:translateY(-50%);color:var(--muted);pointer-events:none}
.export{display:inline-flex;align-items:center;justify-content:center;gap:7px;height:37px;margin-left:auto;padding:0 13px;border:1px solid var(--ink);border-radius:var(--radius-control);background:var(--ink);color:#FFFDF8;font-size:13px;font-weight:600;letter-spacing:-.005em;white-space:nowrap;transition:background-color .14s ease,border-color .14s ease,transform .1s ease}
.export:hover{background:#2C302A;border-color:#2C302A}
.export:active{transform:translateY(1px)}

.table{width:100%;border-collapse:collapse;table-layout:fixed}
.table col.w-order{width:122px}
.table col.w-status{width:150px}
.table col.w-amount{width:140px}
.table col.w-created{width:164px}
.table th,.table td{text-align:left;vertical-align:middle}
.table thead th{padding:9px 18px;background:#FAF8F3;border-bottom:1px solid var(--line);font-size:11px;line-height:1.4;font-weight:600;letter-spacing:.075em;text-transform:uppercase;color:var(--muted);white-space:nowrap}
.table tbody td{height:58px;padding:8px 18px;border-bottom:1px solid var(--line);font-size:13.5px}
.table tbody tr:last-child td{border-bottom:0}
.table tbody tr{transition:background-color .12s ease}
.table tbody tr:hover{background:var(--row-hover)}
.table .col-amount,.table .col-created{text-align:right}
.table td.col-amount{font-size:14px;font-weight:600;font-variant-numeric:tabular-nums;color:var(--ink)}
.table td.col-created{font-size:12.5px;color:var(--muted);font-variant-numeric:tabular-nums;white-space:nowrap}
.th-created{display:inline-flex;align-items:center;justify-content:flex-end;gap:5px;width:100%}
.th-created svg{color:var(--faint)}

.order-id{font-family:var(--font-mono);font-size:12.5px;font-weight:500;letter-spacing:-.01em;color:#3F443B;font-variant-numeric:tabular-nums;white-space:nowrap}
.customer{display:flex;flex-direction:column;gap:1px;min-width:0;line-height:1.25}
.customer-name{display:block;font-size:13.5px;font-weight:500;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.customer-email{display:block;font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.chip{display:inline-flex;align-items:center;gap:6px;height:24px;padding:0 9px 0 8px;border:1px solid transparent;border-radius:6px;font-size:12px;font-weight:600;line-height:1;white-space:nowrap}
.chip .dot{width:6px;height:6px;border-radius:50%;flex:0 0 auto}
.chip-paid{background:var(--paid-bg);border-color:var(--paid-line);color:var(--paid-ink)}
.chip-paid .dot{background:var(--paid-dot)}
.chip-pending{background:var(--pending-bg);border-color:var(--pending-line);color:var(--pending-ink)}
.chip-pending .dot{background:var(--pending-dot)}
.chip-refunded{background:var(--refunded-bg);border-color:var(--refunded-line);color:var(--refunded-ink)}
.chip-refunded .dot{background:var(--refunded-dot)}

.pagination{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:13px 18px;border-top:1px solid var(--line);background:var(--surface)}
.range{margin:0;font-size:12.5px;color:var(--muted);font-variant-numeric:tabular-nums}
.pager{display:flex;align-items:center;gap:4px}
.page-btn{width:32px;height:32px;display:grid;place-items:center;border:1px solid var(--line);border-radius:7px;background:var(--surface-soft);color:var(--faint)}
.page-btn:disabled{cursor:not-allowed;color:#A7AB9F;border-color:var(--line);background:var(--surface-soft)}
.page-current{min-width:32px;height:32px;display:grid;place-items:center;border:1px solid var(--line-strong);border-radius:7px;background:#F1EFE7;font-size:12.5px;font-weight:600;color:var(--ink);font-variant-numeric:tabular-nums}

.empty-demo{margin-top:36px}
.section-head{display:flex;align-items:center;gap:14px;margin-bottom:12px}
.section-title{margin:0;font-family:var(--font-mono);font-size:12px;font-weight:500;letter-spacing:.01em;color:var(--muted);white-space:nowrap}
.section-line{flex:1;height:1px;background:var(--line)}
.empty-panel{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:34px 24px 36px;background:var(--surface-soft);border:1px solid var(--line);border-radius:var(--radius-panel)}
.empty-icon{width:58px;height:58px;border-radius:14px;background:var(--accent-soft);border:1px solid #D6E2D7;display:grid;place-items:center;color:var(--accent);margin-bottom:16px}
.empty-panel h3{margin:0;font-size:16px;font-weight:600;letter-spacing:-.012em;color:var(--ink)}
.empty-panel p{margin:7px 0 0;max-width:40ch;font-size:13.5px;line-height:1.55;color:var(--muted)}
.empty-action{display:inline-flex;align-items:center;justify-content:center;height:36px;margin-top:18px;padding:0 14px;border:1px solid var(--control);border-radius:8px;background:var(--surface-field);color:var(--ink);font-size:13px;font-weight:600;transition:background-color .14s ease,border-color .14s ease}
.empty-action:hover{background:#F3F1EA;border-color:#757267}

@media (max-width:860px){
  .table{display:block;table-layout:auto}
  .table colgroup{display:none}
  .table thead{display:none}
  .table tbody{display:block}
  .table tbody tr{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:"order status" "customer customer" "amount created";align-items:center;column-gap:12px;row-gap:6px;padding:14px 18px;border-bottom:1px solid var(--line)}
  .table tbody tr:last-child{border-bottom:0}
  .table tbody td{display:block;height:auto;padding:0;border:0;text-align:left;min-width:0}
  .table .col-order{grid-area:order}
  .table .col-customer{grid-area:customer}
  .table .col-status{grid-area:status;justify-self:end;text-align:right}
  .table .col-amount{grid-area:amount;text-align:left;font-size:14px}
  .table .col-created{grid-area:created;justify-self:end;text-align:right;font-size:12.5px}
  .customer-name{font-size:14px}
  .customer-email{font-size:12.5px}
}
@media (max-width:760px){
  .appbar-inner{height:54px;padding:0 16px;gap:0}
  .mainnav{display:none}
  .account{height:40px;padding:0 4px}
  .account-name,.account .chev{display:none}
  .page{padding:28px 16px 56px}
  .page-head{margin-bottom:20px}
  .page-head h1{font-size:26px;letter-spacing:-.025em}
  .lede{margin-top:8px;font-size:13px}
  .empty-demo{margin-top:36px}
}
@media (max-width:720px){
  .toolbar{padding:12px;gap:8px}
  .search{flex:1 1 100%}
  .search input{height:40px}
  .filter{flex:1 1 150px;min-width:0}
  .filter select{width:100%;min-width:0;height:40px}
  .export{flex:0 0 auto;height:40px;margin-left:0}
  .table tbody tr{padding:14px}
  .pagination{padding:12px 14px}
  .empty-panel{padding:34px 20px 36px}
  .empty-panel p{font-size:13px}
  .empty-action{height:40px}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{transition:none!important;animation:none!important}
}
